"use client";

import { forwardRef, type ComponentProps } from "react";
import LegacySelectionActions from "../beautiful-ui/primitives/SelectionActions";
import { BeautifulUIRoot } from "../beautiful-ui/BeautifulUIRoot";

export type SelectionActionsProps = NonNullable<ComponentProps<typeof LegacySelectionActions>>;

export const SelectionActions = forwardRef<HTMLDivElement, SelectionActionsProps>((props, ref) => (
  <BeautifulUIRoot ref={ref}>
    <LegacySelectionActions {...props} />
  </BeautifulUIRoot>
));

SelectionActions.displayName = "SelectionActions";

export default SelectionActions;

"use client";

import { useCallback, useEffect, useLayoutEffect, useRef, useState } from "react";
import { Scissors } from "lucide-react";
import { useIcon } from "@/lib/icon-context";
import { Shimmer } from "../atoms/Shimmer";
import { StreamText } from "../atoms/StreamText";
import { useReducedMotion } from "../hooks/useReducedMotion";
import "../beautiful-ui.css";

const DEFAULT_LEAD = "Pistachio holds the top slot all weekend. ";
const DEFAULT_SELECTION =
  "Churn it first thing Saturday so the batch has time to firm up before the afternoon rush.";
const DEFAULT_REWRITE =
  "Churn pistachio first thing Saturday so the batch has time to fully firm before the afternoon rush.";

type Mode = "idle" | "thinking" | "streaming" | "result";

const iconProps = {
  size: 14,
  strokeWidth: 1.8,
  className: "shrink-0",
  "aria-hidden": true,
} as const;

const control =
  "inline-flex h-7 shrink-0 items-center gap-1 rounded-full px-2.5 text-[12px] font-normal text-[var(--ink)] transition-[background-color,color,transform] duration-160 hover:bg-[var(--hover)] active:scale-[0.98]";

const primary =
  "inline-flex h-7 shrink-0 items-center gap-1 rounded-full bg-[var(--ink)] px-2.5 text-[12px] font-normal text-[var(--canvas)] shadow-[var(--shadow-hairline)] transition-[opacity,transform] duration-160 hover:opacity-90 active:scale-[0.98]";

export interface SelectionActionsProps {
  leadText?: string;
  selectedText?: string;
  replacementText?: string;
  onAction?: (action: string, selectedText: string) => void;
  onExplain?: (selectedText: string) => void;
  onKeep?: (replacementText: string) => void;
  onDiscard?: (selectedText: string) => void;
}

export default function SelectionActions({
  leadText = DEFAULT_LEAD,
  selectedText = DEFAULT_SELECTION,
  replacementText = DEFAULT_REWRITE,
  onAction,
  onExplain,
  onKeep,
  onDiscard,
}: SelectionActionsProps = {}) {
  const ExplainIcon = useIcon("message-circle");
  const ImproveIcon = useIcon("lightbulb");
  const ToneIcon = useIcon("heart");
  const GrammarIcon = useIcon("pencil");
  const SendIcon = useIcon("arrow-up");
  const ChevronIcon = useIcon("chevron-right");
  const CheckIcon = useIcon("check");
  const CloseIcon = useIcon("x");
  const RetryIcon = useIcon("rotate-ccw");
  const icons = {
    explain: <ExplainIcon {...iconProps} />,
    improve: <ImproveIcon {...iconProps} />,
    shorten: <Scissors {...iconProps} />,
    tone: <ToneIcon {...iconProps} />,
    grammar: <GrammarIcon {...iconProps} />,
    send: <SendIcon size={16} strokeWidth={2.4} />,
    chevron: <ChevronIcon {...iconProps} />,
    check: <CheckIcon {...iconProps} />,
    close: <CloseIcon {...iconProps} />,
    retry: <RetryIcon {...iconProps} />,
  };
  const reducedMotion = useReducedMotion();
  const [shown, setShown] = useState(false);
  const [mode, setMode] = useState<Mode>("idle");
  const [action, setAction] = useState("Improve");
  const [prompt, setPrompt] = useState("");
  const [expanded, setExpanded] = useState(false);
  const [anchor, setAnchor] = useState({ x: 0, y: 0 });
  const [positioned, setPositioned] = useState(false);

  const hostRef = useRef<HTMLDivElement>(null);
  const selectionRef = useRef<HTMLSpanElement>(null);
  const idleActionRef = useRef<HTMLButtonElement>(null);
  const resultActionRef = useRef<HTMLButtonElement>(null);
  const frameRef = useRef<number | null>(null);

  useEffect(() => {
    if (reducedMotion) {
      setShown(true);
      return;
    }
    const timer = window.setTimeout(() => setShown(true), 240);
    return () => window.clearTimeout(timer);
  }, [reducedMotion]);

  useEffect(() => {
    if (mode !== "thinking") return;
    if (reducedMotion) {
      setMode("result");
      return;
    }
    const timer = window.setTimeout(() => setMode("streaming"), 240);
    return () => window.clearTimeout(timer);
  }, [mode, reducedMotion]);

  useEffect(() => {
    if (mode !== "result") return;
    const frame = requestAnimationFrame(() => resultActionRef.current?.focus());
    return () => cancelAnimationFrame(frame);
  }, [mode]);

  const place = useCallback(() => {
    if (frameRef.current !== null) cancelAnimationFrame(frameRef.current);
    frameRef.current = requestAnimationFrame(() => {
      const host = hostRef.current;
      const selection = selectionRef.current;
      if (!host || !selection) return;

      const bounds = selection.getBoundingClientRect();
      const lines = Array.from(selection.getClientRects());
      const lastLine = lines.at(-1);
      if (!lastLine) return;

      const hostBounds = host.getBoundingClientRect();
      const next = {
        x: Math.round(bounds.left - hostBounds.left + bounds.width / 2),
        y: Math.round(lastLine.bottom - hostBounds.top + 8),
      };

      setAnchor((current) => (current.x === next.x && current.y === next.y ? current : next));
      setPositioned(true);
    });
  }, []);

  useLayoutEffect(() => {
    place();
  }, [mode, place, selectedText, replacementText]);

  useEffect(() => {
    const host = hostRef.current;
    if (!host) return;
    const observer = new ResizeObserver(place);
    observer.observe(host);
    window.addEventListener("resize", place);
    return () => {
      observer.disconnect();
      window.removeEventListener("resize", place);
      if (frameRef.current !== null) cancelAnimationFrame(frameRef.current);
    };
  }, [place]);

  const run = (nextAction: string) => {
    setAction(nextAction);
    setExpanded(false);
    setMode(reducedMotion ? "result" : "thinking");
    onAction?.(nextAction, selectedText);
  };

  const reset = () => {
    setExpanded(false);
    setPrompt("");
    setAction("Improve");
    setMode("idle");
    requestAnimationFrame(() => idleActionRef.current?.focus());
  };

  const keep = () => {
    onKeep?.(replacementText);
    reset();
  };

  const discard = () => {
    onDiscard?.(selectedText);
    reset();
  };

  const explain = () => {
    onExplain?.(selectedText);
    run("Explain");
  };

  const busy = mode === "thinking" || mode === "streaming";
  const visible = shown && positioned;
  const hasPrompt = prompt.trim().length > 0;
  const busyLabel =
    action === "Explain"
      ? "Explaining"
      : action === "Improve"
        ? "Improving"
        : action === "Shorten"
          ? "Shortening"
          : action === "Change tone"
            ? "Changing tone"
            : "Editing";

  return (
    <div className="w-full max-w-[460px]">
      <div ref={hostRef} className="relative pb-12">
        <p className="text-[13px] leading-relaxed text-[var(--ink)]">
          {leadText}
          <span
            ref={selectionRef}
            className="box-decoration-clone rounded-[3px] bg-[color-mix(in_srgb,var(--bui-focus)_14%,var(--surface))] text-[var(--ink)] dark:bg-[var(--bui-focus-tint)]"
          >
            {mode === "idle" || mode === "thinking" ? (
              selectedText
            ) : mode === "streaming" ? (
              <StreamText
                text={replacementText}
                onProgress={place}
                onDone={() => setMode("result")}
              />
            ) : (
              replacementText
            )}
          </span>
        </p>

        {visible ? (
          <div
            className="absolute top-0 left-0 z-10"
            style={{
              transform: `translate3d(${anchor.x}px, ${anchor.y}px, 0) translateX(-50%)`,
              transition: reducedMotion
                ? undefined
                : "transform 240ms cubic-bezier(0.77,0,0.175,1), opacity 160ms ease-out",
              willChange: reducedMotion ? undefined : "transform",
            }}
          >
            <div
              className="flex h-9 w-fit max-w-[calc(100vw-48px)] items-center justify-center gap-0.5 overflow-hidden rounded-full bg-[var(--surface)] p-1 font-sans font-normal text-[var(--ink)] shadow-[var(--shadow-overlay)]"
              style={{
                animation: reducedMotion
                  ? undefined
                  : "pop-in 240ms cubic-bezier(0.23,1,0.32,1) both",
              }}
            >
              <div className="flex w-fit shrink-0 items-center justify-center gap-0.5">
                {busy ? (
                  <span
                    role="status"
                    className="inline-flex h-7 items-center gap-1.5 whitespace-nowrap px-2.5 text-[12px] font-normal text-[var(--ink-2)]"
                  >
                    <span
                      aria-hidden="true"
                      className="size-3 shrink-0 rounded-full border-[1.5px] border-[var(--line-strong)] border-t-ink-2"
                      style={{ animation: "spin 240ms linear infinite" }}
                    />
                    {mode === "thinking" ? (
                      <Shimmer className="text-[12px] font-normal">{busyLabel}…</Shimmer>
                    ) : (
                      <span>{busyLabel}…</span>
                    )}
                  </span>
                ) : null}

                {mode === "result" ? (
                  <>
                    <button ref={resultActionRef} type="button" onClick={keep} className={primary}>
                      {icons.check}
                      Keep
                    </button>
                    <button type="button" onClick={discard} className={control}>
                      {icons.close}
                      Discard
                    </button>
                    <span className="mx-0.5 h-4 w-px shrink-0 bg-[var(--line)]" />
                    <button
                      type="button"
                      aria-label={`Try ${action.toLowerCase()} again`}
                      onClick={() => run(action)}
                      className="flex size-7 shrink-0 items-center justify-center rounded-full text-[var(--ink-3)] transition-[background-color,color,transform] duration-160 hover:bg-[var(--hover-2)] hover:text-[var(--ink-2)] active:scale-[0.98]"
                    >
                      {icons.retry}
                    </button>
                  </>
                ) : null}

                {mode === "idle" ? (
                  hasPrompt ? (
                    <form
                      data-bui-input-group=""
                      className="flex h-7 w-56 shrink-0 items-center rounded-full"
                      onSubmit={(event) => {
                        event.preventDefault();
                        run(prompt.trim());
                      }}
                    >
                      <input
                        value={prompt}
                        onChange={(event) => setPrompt(event.target.value)}
                        aria-label="Describe edits"
                        placeholder="Describe edits"
                        className="h-7 min-w-0 flex-1 bg-transparent pr-2.5 pl-3 text-[12px] text-[var(--ink)] outline-none placeholder:text-[var(--ink-3)]"
                      />
                      <button
                        type="submit"
                        aria-label="Send edit instruction"
                        className="flex size-7 shrink-0 items-center justify-center rounded-full bg-[var(--ink)] text-[var(--surface)] transition-[opacity,transform] duration-160 active:scale-[0.98]"
                      >
                        {icons.send}
                      </button>
                    </form>
                  ) : (
                    <>
                      {!expanded ? (
                        <span className="mx-1 h-4 w-px shrink-0 bg-[var(--line-strong)]" />
                      ) : null}
                      <button
                        ref={idleActionRef}
                        type="button"
                        onClick={explain}
                        className={control}
                      >
                        {icons.explain}
                        Explain
                      </button>
                      <button type="button" onClick={() => run("Improve")} className={control}>
                        {icons.improve}
                        Improve
                      </button>

                      {expanded ? (
                        <>
                          <button type="button" onClick={() => run("Shorten")} className={control}>
                            {icons.shorten}
                            Shorten
                          </button>
                          <button
                            type="button"
                            onClick={() => run("Change tone")}
                            className={control}
                          >
                            {icons.tone}
                            Tone
                          </button>
                          <button
                            type="button"
                            onClick={() => run("Fix grammar")}
                            className={control}
                          >
                            {icons.grammar}
                            Grammar
                          </button>
                        </>
                      ) : null}

                      <span className="mx-0.5 h-4 w-px shrink-0 bg-[var(--line)]" />
                      <button
                        type="button"
                        aria-label={expanded ? "Show fewer actions" : "Show more actions"}
                        aria-expanded={expanded}
                        onClick={() => setExpanded((value) => !value)}
                        className="flex size-7 shrink-0 items-center justify-center rounded-full text-[var(--ink)] transition-[background-color,transform] duration-160 hover:bg-[var(--hover)] active:scale-[0.98]"
                      >
                        <span
                          className="flex transition-transform duration-240"
                          style={{ transform: expanded ? "rotate(180deg)" : "rotate(0deg)" }}
                        >
                          {icons.chevron}
                        </span>
                      </button>
                    </>
                  )
                ) : null}
              </div>
            </div>
          </div>
        ) : null}
      </div>

      <span role="status" aria-live="polite" className="sr-only">
        {busy ? `${busyLabel} selected text` : mode === "result" ? "Rewrite ready" : ""}
      </span>
    </div>
  );
}

"use client";

import "./beautiful-ui.css";
import { forwardRef, type CSSProperties, type HTMLAttributes } from "react";
import { SurfaceProvider, useSurface } from "@/lib/surface-context";
import { useShapeVariant } from "@/lib/shape-context";

export type BeautifulUIRootProps = HTMLAttributes<HTMLDivElement>;

type AdapterStyle = CSSProperties & Record<`--${string}`, string | number>;

function clampSurface(level: number) {
  return Math.max(1, Math.min(8, level));
}

function createAdapterStyle(
  substrate: number,
  surface: number,
  style?: CSSProperties,
): AdapterStyle {
  const inset = clampSurface(substrate + 1);
  const overlay = clampSurface(surface + 2);
  const raisedOverlay = clampSurface(surface + 4);

  return {
    "--page": `var(--surface-${substrate})`,
    "--canvas": `var(--surface-${substrate})`,
    "--surface": `var(--surface-${surface})`,
    "--inset": `var(--surface-${inset})`,
    "--tooltip-bg": `var(--surface-${overlay})`,
    "--overlay-surface": `var(--surface-${overlay})`,
    "--overlay-raised": `var(--surface-${raisedOverlay})`,
    ...style,
  };
}

function useBeautifulUIScope(offset = 2) {
  const substrate = useSurface();
  const surface = clampSurface(substrate + offset);
  const shape = useShapeVariant();

  return {
    shape,
    substrate,
    surface,
    style: createAdapterStyle(substrate, surface),
  };
}

/**
 * Internal compatibility boundary for the adapted primitives. It has no layout
 * box of its own: public components use it internally so consumers inherit the
 * active BoringUI theme, surface level, and radius mode without a wrapper.
 */
export const BeautifulUIRoot = forwardRef<HTMLDivElement, BeautifulUIRootProps>(
  ({ className, style, ...props }, ref) => {
    const scope = useBeautifulUIScope();

    return (
      <SurfaceProvider value={scope.surface}>
        <div
          ref={ref}
          data-bui-component=""
          data-shape={scope.shape}
          data-surface={scope.surface}
          className={["beautiful-ui", "contents", className].filter(Boolean).join(" ")}
          style={{ ...scope.style, ...style }}
          {...props}
        />
      </SurfaceProvider>
    );
  },
);

BeautifulUIRoot.displayName = "BeautifulUIRoot";

/** Applies the same BoringUI scope to content rendered in a body portal. */
export const BeautifulUIPortalRoot = forwardRef<HTMLDivElement, BeautifulUIRootProps>(
  ({ className, style, ...props }, ref) => {
    const scope = useBeautifulUIScope();

    return (
      <SurfaceProvider value={scope.surface}>
        <div
          ref={ref}
          data-bui-component=""
          data-shape={scope.shape}
          data-surface={scope.surface}
          className={["beautiful-ui", className].filter(Boolean).join(" ")}
          style={{ ...scope.style, ...style }}
          {...props}
        />
      </SurfaceProvider>
    );
  },
);

BeautifulUIPortalRoot.displayName = "BeautifulUIPortalRoot";

export default BeautifulUIRoot;

